    image_patch = ImagePatch(image)
    horse_patches = image_patch.find("horse")

    if len(horse_patches) < 3:
        return image_patch  # Not enough horses to form a line

    # Sort by depth to find the middle horse
    horse_patches.sort(key=lambda p: p.compute_depth())
    middle_horse = horse_patches[1]

    # Find the horse behind the middle one
    behind_horse = None
    for horse in horse_patches:
        if horse.compute_depth() < middle_horse.compute_depth() and horse != middle_horse:
            if behind_horse is None or horse.compute_depth() > behind_horse.compute_depth():
                behind_horse = horse

    if behind_horse is None:
        return middle_horse  # No horse behind the middle one

    return behind_horse

