@staticmethod
def distance_to_nearest_object(self, object_name: str) -> float:
    patches = self.find(object_name)
    if not patches: return float('inf')
    return min(p.distance_to_edge() for p in patches)

@staticmethod
def distance_to_edge(self) -> float:
    width, height = self.image.shape[:2]
    center_x, center_y = (self.left + self.right) / 2, (self.lower + self.upper) / 2
    return min(center_x, width - center_x, center_y, height - center_y)

